void print_prime_numbers() 
{ 
    bool prime[100+1]; 
    memset(prime, true, sizeof(prime));

    for (int p = 2; p*p < 100+1; p++) 
    {   
        // If prime[p] is not changed, then it is a prime 
        if (prime[p] == true) 
        { 
            // Update all multiples of p 
            for (int i=p*p; i <= 100; i += p) 
                prime[i] = false; 
        } 
    } 

    // Print all prime numbers 
    for (int p=2; p <= 100; p++) 
       if (prime[p]) 
          cout << p << " "; 
}

